                    <h2 id="endpoints-POSTapi-quote-requests">POST /api/quote-requests
Le visiteur envoie son panier de devis (plusieurs produits en une seule demande).</h2>

<p>
</p>



<span id="example-requests-POSTapi-quote-requests">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://127.0.0.1:8000/api/quote-requests" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"first_name\": \"b\",
    \"last_name\": \"n\",
    \"company\": \"g\",
    \"phone\": \"z\",
    \"email\": \"rempel.chadrick@example.org\",
    \"city\": \"l\",
    \"comment\": \"architecto\",
    \"items\": [
        {
            \"product_id\": \"architecto\",
            \"quantity\": 22
        }
    ]
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://127.0.0.1:8000/api/quote-requests"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "first_name": "b",
    "last_name": "n",
    "company": "g",
    "phone": "z",
    "email": "rempel.chadrick@example.org",
    "city": "l",
    "comment": "architecto",
    "items": [
        {
            "product_id": "architecto",
            "quantity": 22
        }
    ]
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

