    "Accept": "application/json",
};

const body = new FormData();
body.append('name', 'b');
body.append('company', 'n');
body.append('phone', 'g');
body.append('email', 'rowan.gulgowski@example.com');
body.append('city', 'd');
body.append('establishment_type', 'l');
body.append('description', 'Eius et animi quos velit et.');
