    "price_fcfa": 60,
    "availability": "en_stock",
    "is_active": true,
    "is_featured": true,
    "meta_title": "d",
    "meta_description": "l"
};

fetch(url, {
    method: "PUT",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

