                    <h2 id="endpoints-POSTapi-catalog-import">POST /api/admin/catalog-import</h2>

<p>
</p>

<p>Champs attendus (multipart/form-data) :</p>
<ul>
<li>catalog_file : le fichier Excel (Produits / Caracteristiques / Images)</li>
<li>images_zip   : (optionnel) un ZIP contenant toutes les images référencées</li>
</ul>

<span id="example-requests-POSTapi-catalog-import">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://127.0.0.1:8000/api/catalog-import" \
    --header "Content-Type: multipart/form-data" \
    --header "Accept: application/json" \
    --form "catalog_file=@C:\Users\HP\AppData\Local\Temp\php714.tmp" \
    --form "images_zip=@C:\Users\HP\AppData\Local\Temp\php715.tmp" </code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://127.0.0.1:8000/api/catalog-import"
);

const headers = {
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('catalog_file', document.querySelector('input[name="catalog_file"]').files[0]);
body.append('images_zip', document.querySelector('input[name="images_zip"]').files[0]);

fetch(url, {
    method: "POST",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>

